<?php
namespace App\Core;
final class AssetLibrary
{
    public static function path(string $relative): string { $base=realpath(dirname(__DIR__,2).'/public/uploads'); if (!$base||str_contains($relative,'..')||str_contains($relative,'\\')||preg_match('~(?:^|/)\.~',$relative)) throw new \InvalidArgumentException('Archivo no permitido.'); $path=realpath($base.'/'.$relative); if (!$path||!str_starts_with(str_replace('\\','/',$path),str_replace('\\','/',$base).'/')||!is_file($path)||is_link($base.'/'.$relative)) throw new \InvalidArgumentException('Archivo no encontrado.'); return $path; }
    public static function items(string $q=''): array { $base=dirname(__DIR__,2).'/public/uploads'; $out=[]; if (!is_dir($base)) return []; $iterator=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($base,\FilesystemIterator::SKIP_DOTS)); foreach ($iterator as $file) { if (count($out)>=1000) break; if (!$file->isFile()||$file->isLink()||!in_array(strtolower($file->getExtension()),['png','jpg','jpeg','gif','webp','pdf','txt','csv','zip'],true)) continue; $relative=str_replace('\\','/',substr($file->getPathname(),strlen($base)+1)); if (preg_match('~(?:^|/)\\.~',$relative)) continue; if ($q!==''&&mb_stripos($relative,$q)===false) continue; $info=@getimagesize($file->getPathname()); $out[]=['path'=>$relative,'url'=>'/uploads/'.implode('/',array_map('rawurlencode',explode('/',$relative))),'bytes'=>$file->getSize(),'image'=>$info!==false,'dimensions'=>$info?$info[0].' × '.$info[1]:'—']; } return $out; }
    public static function webp(string $relative): string { $path=self::path($relative); $info=@getimagesize($path); if (!$info||!in_array($info[2],[IMAGETYPE_PNG,IMAGETYPE_JPEG,IMAGETYPE_WEBP],true)||filesize($path)>10485760||$info[0]*$info[1]>16777216) throw new \InvalidArgumentException('Selecciona PNG, JPEG o WebP de hasta 10 MB y 16 millones de píxeles.'); $image=match($info[2]) { IMAGETYPE_PNG=>@imagecreatefrompng($path),IMAGETYPE_JPEG=>@imagecreatefromjpeg($path),default=>@imagecreatefromwebp($path) }; if (!$image) throw new \InvalidArgumentException('Imagen inválida.'); $dir=dirname(__DIR__,2).'/public/uploads/dam'; if (!is_dir($dir)&&!mkdir($dir,0755,true)) throw new \RuntimeException('No se pudo crear el directorio.'); $name='webp-'.bin2hex(random_bytes(16)).'.webp'; try { imagesavealpha($image,true); if (!imagewebp($image,$dir.'/'.$name,80)) throw new \RuntimeException('No se pudo convertir la imagen.'); } finally { imagedestroy($image); } return '/uploads/dam/'.$name; }
}
